namespace sv_7fc6cfcf545d49719af6a70acc842fb2.Services;

public record Product(int Id, string Name, decimal Price, string Category, double Rating, bool InStock, string ImageUrl);
public record ProductFilter(List<string>? Categories, decimal? MinPrice, decimal? MaxPrice, bool InStockOnly);
public record PagedResult<T>(List<T> Items, int TotalCount, int Page, int PageSize);

public interface IProductService
{
    Task<PagedResult<Product>> SearchAsync(ProductFilter filter, string sortBy, int page, int pageSize);
    Task<List<string>> GetCategoriesAsync();
}

@page "/catalog"
@using sv_7fc6cfcf545d49719af6a70acc842fb2.Services
@inject IProductService ProductService
@rendermode InteractiveServer

<PageTitle>Product Catalog</PageTitle>

<h1 class="mb-4">Product Catalog</h1>

@if (_error is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @_error
        <button class="btn btn-sm btn-outline-danger ms-3" @onclick="RetryAsync">Retry</button>
    </div>
}
else
{
    <div class="d-flex flex-row gap-4">
        @* ── Left Sidebar (Filters) ── *@
        <div style="min-width:250px;width:25%;" class="flex-shrink-0">
            <div class="card">
                <div class="card-header fw-semibold">Filters</div>
                <div class="card-body">
                    @* Categories *@
                    <h6>Category</h6>
                    @if (_categories is null)
                    {
                        <p class="text-muted small">Loading…</p>
                    }
                    else
                    {
                        @foreach (var cat in _categories)
                        {
                            <div class="form-check">
                                <input class="form-check-input" type="checkbox" id="@($"cat-{cat}")"
                                       checked="@_selectedCategories.Contains(cat)"
                                       @onchange="e => ToggleCategory(cat, (bool)e.Value!)" />
                                <label class="form-check-label" for="@($"cat-{cat}")">@cat</label>
                            </div>
                        }
                    }

                    <hr />

                    @* Price range *@
                    <h6>Price Range</h6>
                    <div class="mb-2">
                        <label class="form-label small mb-0">Min Price</label>
                        <input type="number" class="form-control form-control-sm"
                               min="0" step="0.01" placeholder="0"
                               @bind="_minPrice" @bind:event="oninput" />
                    </div>
                    <div class="mb-2">
                        <label class="form-label small mb-0">Max Price</label>
                        <input type="number" class="form-control form-control-sm"
                               min="0" step="0.01" placeholder="Any"
                               @bind="_maxPrice" @bind:event="oninput" />
                    </div>

                    <hr />

                    @* In‑stock toggle *@
                    <div class="form-check mb-3">
                        <input class="form-check-input" type="checkbox" id="inStockOnly"
                               @bind="_inStockOnly" />
                        <label class="form-check-label" for="inStockOnly">In Stock Only</label>
                    </div>

                    @* Action buttons *@
                    <div class="d-grid gap-2">
                        <button class="btn btn-primary btn-sm" @onclick="ApplyFiltersAsync" disabled="@_loading">
                            Apply Filters
                        </button>
                        <button class="btn btn-outline-secondary btn-sm" @onclick="ClearFiltersAsync" disabled="@_loading">
                            Clear Filters
                        </button>
                    </div>
                </div>
            </div>
        </div>

        @* ── Main Content Area ── *@
        <div class="flex-grow-1" style="width:75%;">
            @* Toolbar *@
            <div class="d-flex justify-content-between align-items-center mb-3">
                <div>
                    <label class="form-label small mb-0 me-1">Sort by</label>
                    <select class="form-select form-select-sm d-inline-block w-auto"
                            @onchange="OnSortChangedAsync">
                        @foreach (var opt in _sortOptions)
                        {
                            <option value="@opt.Value" selected="@(opt.Value == _sortBy)">@opt.Label</option>
                        }
                    </select>
                </div>

                <span class="text-muted small">
                    @if (_result is not null && _result.TotalCount > 0)
                    {
                        var first = (_result.Page - 1) * _result.PageSize + 1;
                        var last = Math.Min(_result.Page * _result.PageSize, _result.TotalCount);
                        @($"Showing {first}–{last} of {_result.TotalCount} products")
                    }
                </span>
            </div>

            @* Content states *@
            @if (_loading)
            {
                <div class="text-center py-5">
                    <div class="spinner-border" role="status">
                        <span class="visually-hidden">Loading…</span>
                    </div>
                    <p class="mt-2 text-muted">Loading products…</p>
                </div>
            }
            else if (_result is null || _result.Items.Count == 0)
            {
                <div class="alert alert-info text-center" role="alert">
                    No products found. Try adjusting your filters.
                </div>
            }
            else
            {
                @* Product grid *@
                <div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4 mb-4">
                    @foreach (var product in _result.Items)
                    {
                        <div class="col">
                            <div class="card h-100 shadow-sm product-card"
                                 @onclick="() => OnProductSelected.InvokeAsync(product.Id)"
                                 style="cursor:pointer;">
                                <div class="card-img-top bg-light d-flex align-items-center justify-content-center"
                                     style="height:180px;" role="img" aria-label="@product.Name">
                                    <span class="text-muted">@product.Name</span>
                                </div>
                                <div class="card-body d-flex flex-column">
                                    <h6 class="card-title">@product.Name</h6>
                                    <p class="card-text fw-bold text-primary mb-1">@product.Price.ToString("C")</p>
                                    <p class="card-text mb-2">
                                        @RenderStars(product.Rating)
                                    </p>
                                    @if (!product.InStock)
                                    {
                                        <span class="badge bg-danger mb-2">Out of Stock</span>
                                    }
                                    <div class="mt-auto">
                                        <button class="btn btn-sm btn-success w-100"
                                                disabled="@(!product.InStock)"
                                                @onclick="() => { }" @onclick:stopPropagation="true">
                                            Add to Cart
                                        </button>
                                    </div>
                                </div>
                            </div>
                        </div>
                    }
                </div>

                @* Pagination *@
                @{
                    var totalPages = (int)Math.Ceiling((double)_result.TotalCount / _result.PageSize);
                }
                @if (totalPages > 1)
                {
                    <nav aria-label="Product pagination">
                        <ul class="pagination justify-content-center">
                            <li class="page-item @(_currentPage <= 1 ? "disabled" : "")">
                                <button class="page-link" @onclick="() => GoToPageAsync(_currentPage - 1)"
                                        disabled="@(_currentPage <= 1)">
                                    Previous
                                </button>
                            </li>
                            @for (var p = 1; p <= totalPages; p++)
                            {
                                var page = p;
                                <li class="page-item @(page == _currentPage ? "active" : "")">
                                    <button class="page-link" @onclick="() => GoToPageAsync(page)">@page</button>
                                </li>
                            }
                            <li class="page-item @(_currentPage >= totalPages ? "disabled" : "")">
                                <button class="page-link" @onclick="() => GoToPageAsync(_currentPage + 1)"
                                        disabled="@(_currentPage >= totalPages)">
                                    Next
                                </button>
                            </li>
                        </ul>
                    </nav>
                }
            }
        </div>
    </div>
}

@code {
    [Parameter]
    public EventCallback<int> OnProductSelected { get; set; }

    // ── Filter state ──
    private List<string>? _categories;
    private readonly HashSet<string> _selectedCategories = new();
    private decimal? _minPrice;
    private decimal? _maxPrice;
    private bool _inStockOnly;

    // ── Sort / page state ──
    private string _sortBy = "price_asc";
    private int _currentPage = 1;
    private const int PageSize = 9;

    // ── Results ──
    private PagedResult<Product>? _result;
    private bool _loading = true;
    private string? _error;

    private static readonly (string Value, string Label)[] _sortOptions =
    {
        ("price_asc",   "Price: Low to High"),
        ("price_desc",  "Price: High to Low"),
        ("name_asc",    "Name: A–Z"),
        ("rating_desc", "Rating: Highest"),
    };

    protected override async Task OnInitializedAsync()
    {
        await LoadAsync();
    }

    private async Task LoadAsync()
    {
        try
        {
            _error = null;
            _loading = true;

            var categoriesTask = _categories is null
                ? ProductService.GetCategoriesAsync()
                : Task.FromResult(_categories);

            var searchTask = ProductService.SearchAsync(BuildFilter(), _sortBy, _currentPage, PageSize);

            await Task.WhenAll(categoriesTask, searchTask);

            _categories = await categoriesTask;
            _result = await searchTask;
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private ProductFilter BuildFilter() =>
        new(
            Categories: _selectedCategories.Count > 0 ? _selectedCategories.ToList() : null,
            MinPrice: _minPrice,
            MaxPrice: _maxPrice,
            InStockOnly: _inStockOnly
        );

    private void ToggleCategory(string category, bool selected)
    {
        if (selected)
            _selectedCategories.Add(category);
        else
            _selectedCategories.Remove(category);
    }

    private async Task ApplyFiltersAsync()
    {
        _currentPage = 1;
        await SearchAsync();
    }

    private async Task ClearFiltersAsync()
    {
        _selectedCategories.Clear();
        _minPrice = null;
        _maxPrice = null;
        _inStockOnly = false;
        _currentPage = 1;
        _sortBy = "price_asc";
        await SearchAsync();
    }

    private async Task OnSortChangedAsync(ChangeEventArgs e)
    {
        _sortBy = e.Value?.ToString() ?? "price_asc";
        _currentPage = 1;
        await SearchAsync();
    }

    private async Task GoToPageAsync(int page)
    {
        _currentPage = page;
        await SearchAsync();
    }

    private async Task SearchAsync()
    {
        try
        {
            _error = null;
            _loading = true;
            _result = await ProductService.SearchAsync(BuildFilter(), _sortBy, _currentPage, PageSize);
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task RetryAsync() => await LoadAsync();

    private static string RenderStars(double rating)
    {
        var full = (int)Math.Round(rating);
        var empty = 5 - full;
        return new string('★', full) + new string('☆', empty);
    }
}

